select public.prepify_load_bank('Maths', 6, $j$[["In the sexagesimal system, one degree (1°) is equal to:",["60 minutes","100 minutes","60 seconds","3600 minutes"],"A",3,0,"df6a761a1d34"],["How many seconds are there in one degree?",["60″","360″","600″","3600″"],"D",3,0,"070b692c4b47"],["The radian measure of a complete angle (360°) is:",["π radians","3π/2 radians","2π radians","4π radians"],"C",3,0,"a59125c0b307"],["1 radian is approximately equal to:",["45° 00′ 00″","57° 17′ 45″","60° 00′ 00″","90° 00′ 00″"],"B",3,0,"cb4cbb560a6b"],["To convert an angle from degrees to radians, multiply by:",["π/360","π/180","180/π","360/π"],"B",3,0,"68a81e72ef15"],["The radian measure of 90° is:",["π/4","π/3","π/2","π"],"C",3,0,"88220f256547"],["The length of a circular arc with radius r and central angle θ (in radians) is:",["l = r²θ","l = rθ","l = θ/r","l = 2πr/θ"],"B",3,0,"a73f4d963b00"],["The area of a sector of a circle with radius r and central angle θ radians is:",["A = rθ","A = r²θ","A = ½ r²θ","A = πr²θ"],"C",3,0,"3a1aadfe9d2c"],["A circle has radius 6 cm and its sector has a central angle of π/3 radians. What is the arc length?",["π cm","2π cm","3π cm","6π cm"],"B",3,0,"ea3e7385b541"],["In a right-angled triangle ABC with ∠C = 90°, sin θ is defined as:",["Base / Hypotenuse","Perpendicular / Hypotenuse","Perpendicular / Base","Hypotenuse / Perpendicular"],"B",3,0,"cfd5bcb15327"],["Which of the following is the reciprocal of cos θ?",["sin θ","tan θ","cosec θ","sec θ"],"D",3,0,"587854a85e56"],["The value of tan 45° is:",["0","1/(√2)","1","√3"],"C",3,0,"8154307dee5f"],["The value of sin 30° is:",["1","(√3)/2","1/(√2)","1/2"],"D",3,0,"7fe8274d03c5"],["The value of cos 60° is:",["(√3)/2","1/2","1/(√2)","0"],"B",3,0,"ae6a5a53c6ca"],["sin 90° is equal to:",["0","1/2","(√3)/2","1"],"D",3,0,"a3e1343feedc"],["The value of cos 180° is:",["1","0","−1","undefined"],"C",3,0,"ff98d204c60a"],["tan 90° is:",["0","1","−1","undefined"],"D",3,0,"df42fe6d8a27"],["cot θ is equal to:",["(sin θ)/(cos θ)","(cos θ)/(sin θ)","1/(sin θ)","1/(sec θ)"],"B",3,0,"d3385d137e7e"],["In which quadrant are both sin θ and cos θ positive?",["1st quadrant","2nd quadrant","3rd quadrant","4th quadrant"],"A",3,0,"7ae8dd4e573c"],["In the second quadrant, which trigonometric ratio is positive?",["cos θ","tan θ","sin θ","cot θ"],"C",3,0,"f823c28607a6"],["In the third quadrant, which of the following is positive?",["sin θ","cos θ","tan θ","sec θ"],"C",3,0,"92a8252322bb"],["Which of the following is a Pythagorean identity?",["sin²θ − cos²θ = 1","sin²θ + cos²θ = 1","sin θ + cos θ = 1","sin²θ × cos²θ = 1"],"B",3,0,"b55a241505d0"],["sec²θ − tan²θ equals:",["0","−1","2","1"],"D",3,0,"dfc9acf1e29d"],["cosec²θ − cot²θ equals:",["2","−1","1","0"],"C",3,0,"d96c6291059b"],["tan θ is equal to:",["(cos θ)/(sin θ)","(sin θ)/(cos θ)","sin θ × cos θ","1/(cos θ)"],"B",3,0,"396af54c24f9"],["The angle of elevation is measured:",["Below the horizontal line","Along the vertical","Above the horizontal line","Along the ground"],"C",3,0,"52031c6c56fe"],["The angle between the horizontal line and the line of sight to an object below the observer is called:",["Angle of elevation","Angle of depression","Angle of incidence","Bearing angle"],"B",3,0,"68b53a4b20c6"],["A vertical pole is 10 m high. The angle of elevation of its top from a point on the ground is 45°. The distance of the point from the base of the pole is:",["5 m","10/(√2) m","10 m","20 m"],"C",3,0,"9768b7057fcf"],["A ladder 10 m long leans against a vertical wall making an angle of 60° with the wall. The height of the ladder along the wall is:",["10√3 m","5 m","10 m","5√3 m"],"B",3,0,"afb7c468e4e5"],["Bearings are measured clockwise from:",["East","South","West","North"],"D",3,0,"019b177c674c"],["A three-figure bearing is always written using exactly:",["1 digit","2 digits","3 digits","4 digits"],"C",3,0,"2ec87be18844"],["The three-figure bearing of due East is:",["000°","090°","180°","270°"],"B",3,0,"554e1d0a4874"],["The three-figure bearing of due South is:",["090°","135°","180°","270°"],"C",3,0,"b5586470cf6e"],["The three-figure bearing of due West is:",["090°","180°","270°","360°"],"C",3,0,"ac67d60279cd"],["The bearing of the South-West direction is:",["045°","135°","225°","315°"],"C",3,0,"b73c0c3d71dd"],["North-East direction has a bearing of:",["045°","090°","135°","315°"],"A",3,0,"3f42983f2610"],["If an automobile travels at a bearing of 070° from city A to city B, the bearing from city B back to city A is:",["070°","110°","250°","290°"],"C",3,1,"d4097edc799d"],["The value of cos 0° is:",["0","1","−1","undefined"],"B",1,0,"ff98d204c60a"],["sec θ is equal to:",["1/(cos θ)","1/(sin θ)","(sin θ)/(cos θ)","cos θ"],"A",3,0,"d3385d137e7e"],["In a right-angled triangle, cos θ is defined as:",["Base / Hypotenuse","Perpendicular / Hypotenuse","Perpendicular / Base","Hypotenuse / Base"],"A",3,0,"cfd5bcb15327"],["The three-figure bearing of South-East is:",["045°","135°","225°","315°"],"B",3,0,"3f42983f2610"],["Which of these is a Pythagorean identity?",["1 + tan²θ = sec²θ","1 − tan²θ = sec²θ","tan θ + sec θ = 1","tan²θ = 1 + sec²θ"],"A",5,0,"b55a241505d0"],["In the fourth quadrant, which trigonometric ratio is positive?",["sin θ","tan θ","cos θ","cot θ"],"C",3,0,"f823c28607a6"],["30° in radians is:",["π/3","π/6","3π/2","5π/6"],"B",3,0,"gen-maths-m6-degrees-radians"],["60° in radians is:",["π","π/3","π/2","π/4"],"B",3,0,"gen-maths-m6-degrees-radians"],["90° in radians is:",["2π/3","π/2","π/4","2π"],"B",3,0,"gen-maths-m6-degrees-radians"],["45° in radians is:",["π/6","π/4","π/3","2π/3"],"B",3,0,"gen-maths-m6-degrees-radians"],["5π/6 radians in degrees is:",["30°","150°","45°","120°"],"B",3,0,"gen-maths-m6-degrees-radians"],["120° in radians is:",["3π/4","π","2π","2π/3"],"D",3,0,"gen-maths-m6-degrees-radians"],["The value of sin 45° is:",["1/2","1/√2","2","√3"],"B",3,0,"gen-maths-m6-special-values"],["The value of tan 0° is:",["1","2","0","1/√3"],"C",3,0,"gen-maths-m6-special-values"],["The value of cos 30° is:",["√3/2","2","1/2","1/√3"],"A",3,0,"gen-maths-m6-special-values"],["The value of tan 30° is:",["1/√3","1/2","1","√3"],"A",3,0,"gen-maths-m6-special-values"],["The value of sin 0° is:",["1","2","1/√3","0"],"D",3,0,"gen-maths-m6-special-values"],["The value of tan 60° is:",["√3/2","0","2","√3"],"D",3,0,"gen-maths-m6-special-values"],["In a right-angled triangle, the side opposite angle θ is 8 cm, the adjacent side is 15 cm and the hypotenuse is 17 cm. The value of tan θ is:",["15/8","15/17","8/17","8/15"],"D",3,0,"gen-maths-m6-triangle-ratio"],["In a right-angled triangle, the side opposite angle θ is 3 cm, the adjacent side is 4 cm and the hypotenuse is 5 cm. The value of cos θ is:",["3/4","3/5","4/3","4/5"],"D",3,0,"gen-maths-m6-triangle-ratio"],["In a right-angled triangle, the side opposite angle θ is 8 cm, the adjacent side is 15 cm and the hypotenuse is 17 cm. The value of sin θ is:",["15/17","8/17","15/8","8/15"],"B",3,0,"gen-maths-m6-triangle-ratio"],["In a right-angled triangle, the side opposite angle θ is 9 cm, the adjacent side is 12 cm and the hypotenuse is 15 cm. The value of tan θ is:",["4/5","3/5","4/3","3/4"],"D",3,0,"gen-maths-m6-triangle-ratio"],["In a right-angled triangle, the side opposite angle θ is 9 cm, the adjacent side is 12 cm and the hypotenuse is 15 cm. The value of cos θ is:",["4/3","4/5","3/5","3/4"],"B",3,0,"gen-maths-m6-triangle-ratio"],["In a right-angled triangle, the side opposite angle θ is 7 cm, the adjacent side is 24 cm and the hypotenuse is 25 cm. The value of sin θ is:",["7/24","7/25","24/25","24/7"],"B",3,0,"gen-maths-m6-triangle-ratio"],["A ship sails from port A to port B on a bearing of 345°. The bearing of A from B is:",["015°","165°","345°","075°"],"B",3,1,"d4097edc799d"],["A ship sails from port A to port B on a bearing of 295°. The bearing of A from B is:",["295°","065°","025°","115°"],"D",3,1,"d4097edc799d"],["A ship sails from port A to port B on a bearing of 195°. The bearing of A from B is:",["165°","015°","285°","195°"],"B",3,1,"d4097edc799d"],["A ship sails from port A to port B on a bearing of 010°. The bearing of A from B is:",["170°","010°","350°","190°"],"D",3,1,"d4097edc799d"],["A ship sails from port A to port B on a bearing of 100°. The bearing of A from B is:",["260°","100°","280°","080°"],"C",3,1,"d4097edc799d"],["A ship sails from port A to port B on a bearing of 190°. The bearing of A from B is:",["280°","010°","170°","190°"],"B",3,1,"d4097edc799d"],["The direction N60°E written as a three-figure bearing is:",["060°","120°","240°","300°"],"A",3,0,"gen-maths-m6-compass-bearing"],["The direction N20°W written as a three-figure bearing is:",["340°","020°","160°","200°"],"A",3,0,"gen-maths-m6-compass-bearing"],["The direction N15°E written as a three-figure bearing is:",["015°","345°","165°","195°"],"A",3,0,"gen-maths-m6-compass-bearing"],["The direction S40°E written as a three-figure bearing is:",["140°","040°","320°","220°"],"A",3,0,"gen-maths-m6-compass-bearing"],["The direction S70°W written as a three-figure bearing is:",["290°","110°","250°","070°"],"C",3,0,"gen-maths-m6-compass-bearing"],["The direction S20°W written as a three-figure bearing is:",["160°","340°","200°","020°"],"C",3,0,"gen-maths-m6-compass-bearing"],["A circle has radius 3 cm. The length of the arc cut off by a central angle of 0.5 radians is:",["1.5 cm","6 cm","3.5 cm","2.25 cm"],"A",3,0,"gen-maths-m6-arc-length"],["A circle has radius 3 cm. The length of the arc cut off by a central angle of 2.5 radians is:",["7.5 cm","1.2 cm","5.5 cm","11.25 cm"],"A",3,0,"gen-maths-m6-arc-length"],["A circle has radius 10 cm. The length of the arc cut off by a central angle of 1.5 radians is:",["6.67 cm","11.5 cm","15 cm","75 cm"],"C",3,0,"gen-maths-m6-arc-length"],["A circle has radius 12 cm. The length of the arc cut off by a central angle of 2.5 radians is:",["30 cm","14.5 cm","180 cm","4.8 cm"],"A",3,0,"gen-maths-m6-arc-length"],["A circle has radius 8 cm. The length of the arc cut off by a central angle of 3 radians is:",["96 cm","24 cm","2.67 cm","11 cm"],"B",3,0,"gen-maths-m6-arc-length"],["A circle has radius 12 cm. The length of the arc cut off by a central angle of 0.5 radians is:",["6 cm","24 cm","12.5 cm","36 cm"],"A",3,0,"gen-maths-m6-arc-length"]]$j$::jsonb, true);
select public.prepify_load_bank('Maths', 7, $j$[["The distance between the points (0, 0) and (3, 4) is:",["5","7","12","25"],"A",1,0,"f259bff26da6"],["The distance between (1, 2) and (4, 6) is:",["3","4","5","7"],"C",3,0,"7298a6dd6098"],["The distance between (−2, 3) and (4, −5) is:",["8","10","14","√28"],"B",5,0,"2a864c5e90a8"],["The midpoint of the segment joining (2, 4) and (6, 8) is:",["(4, 6)","(8, 12)","(2, 2)","(3, 5)"],"A",1,0,"f9cce6c5f9d4"],["The midpoint of the segment joining (−3, 5) and (5, −1) is:",["(1, 2)","(2, 4)","(−4, 3)","(8, −6)"],"A",3,0,"a051e50f876d"],["The point (−3, 4) lies in the:",["first quadrant","second quadrant","third quadrant","fourth quadrant"],"B",1,0,"043574c06b63"],["The point (5, −2) lies in the:",["first quadrant","second quadrant","third quadrant","fourth quadrant"],"D",1,0,"97f868398df1"],["The point (0, 7) lies on the:",["x-axis","y-axis","origin","third quadrant"],"B",1,0,"1a09a5c77c1d"],["The abscissa (x-coordinate) of the point (−4, 9) is:",["9","−4","5","−9"],"B",1,0,"f5bc85a2d676"],["Both coordinates of a point are negative. The point lies in the:",["first quadrant","second quadrant","third quadrant","fourth quadrant"],"C",1,0,"740afd4dfd69"],["M(3, 4) is the midpoint of AB and A is (1, 2). The coordinates of B are:",["(5, 6)","(2, 3)","(4, 6)","(7, 10)"],"A",5,0,"33d73043ba07"],["The distance of the point (−6, 8) from the origin is:",["2","10","14","100"],"B",3,0,"cf0ba99be596"],["The distance between (3, −2) and (3, 5) is:",["3","5","7","8"],"C",3,0,"3774d7aefc22"],["The distance between (−4, 1) and (2, 1) is:",["2","4","6","8"],"C",3,0,"1ea431416b28"],["The formula for the distance between (x₁, y₁) and (x₂, y₂) is:",["√((x₂ − x₁)² + (y₂ − y₁)²)","(x₂ − x₁) + (y₂ − y₁)","√(x₂ + x₁)²","(x₂ − x₁)(y₂ − y₁)"],"A",1,0,"3a1c7208cd37"],["The midpoint of the segment joining (x₁, y₁) and (x₂, y₂) is:",["((x₁ + x₂)/2, (y₁ + y₂)/2)","((x₁ − x₂)/2, (y₁ − y₂)/2)","(x₁ + x₂, y₁ + y₂)","(x₁x₂, y₁y₂)"],"A",1,0,"24bcba690672"],["On a