select public.prepify_load_bank('Maths', 8, $j$[["The slope of the line through (1, 2) and (3, 6) is:",["1/2","2","4","8"],"B",1,0,"5ec5fe8c20cf"],["The slope of the line through (2, 5) and (4, 1) is:",["2","−2","1/2","−1/2"],"B",3,0,"9462db0391d6"],["The slope of the line y = 3x + 4 is:",["3","4","7","−3"],"A",1,0,"19aed16c6020"],["The y-intercept of the line y = 3x + 4 is:",["3","4","−4","7"],"B",1,0,"ee1d97fead77"],["The slope of a horizontal line is:",["0","1","−1","undefined"],"A",1,0,"83e3ebe8e310"],["The slope of a vertical line is:",["0","1","−1","undefined"],"D",3,0,"94cc634fef52"],["Two non-vertical lines are parallel if their slopes are:",["equal","negative reciprocals","both zero only","opposite in sign"],"A",3,0,"9dc0ae315084"],["Two lines with slopes m₁ and m₂ are perpendicular if:",["m₁ = m₂","m₁m₂ = 1","m₁m₂ = −1","m₁ + m₂ = 0"],"C",3,0,"222e98a0d18a"],["The slope of a line perpendicular to a line of slope 2 is:",["2","−2","1/2","−1/2"],"D",3,0,"b2fb46194fdb"],["The equation of the line with slope 2 and y-intercept −3 is:",["y = 2x − 3","y = −3x + 2","y = 2x + 3","2y = x − 3"],"A",1,0,"f069586ea392"],["The line 2x + y = 6 cuts the x-axis at:",["(6, 0)","(3, 0)","(0, 3)","(0, 6)"],"B",3,0,"3de9207895b3"],["For the line 3x − 2y = 12, the y-intercept is:",["6","−6","4","−4"],"B",5,0,"9c048e2fb7f2"],["The equation of the line through (1, 3) with slope 2 is:",["y = 2x + 1","y = 2x + 3","y = 3x + 2","y = 2x − 1"],"A",3,0,"63c4ea0aba11"],["The equation of the line through (2, 1) and (4, 5) is:",["y = 2x − 3","y = 2x + 1","y = x − 1","y = 3x − 5"],"A",5,0,"75dc85c4bc04"],["Which point lies on the line y = 2x + 1?",["(1, 2)","(2, 5)","(3, 6)","(0, 2)"],"B",1,0,"13578133a83b"],["The lines y = 3x + 2 and y = 3x − 5 are:",["parallel","perpendicular","the same line","intersecting at the origin"],"A",3,0,"afa1b996e319"],["The lines y = 2x + 1 and y = −½x + 3 are:",["parallel","perpendicular","the same line","both horizontal"],"B",5,0,"a66b225f2044"],["A line makes an angle of 45° with the positive x-axis. Its slope is:",["0","1","−1","√3"],"B",3,0,"e3f2f9f60ef0"],["The equation of the x-axis is:",["x = 0","y = 0","y = x","x + y = 0"],"B",1,0,"e903c801fd98"],["The line parallel to the x-axis and passing through (0, 4) is:",["x = 4","y = 4","y = 4x","x + y = 4"],"B",3,0,"630ee651cbb6"],["The line with x-intercept 2 and y-intercept 3 is:",["3x + 2y = 6","2x + 3y = 6","x + y = 5","3x − 2y = 6"],"A",5,0,"514dd352ea25"],["A taxi charges a fixed Rs 100 plus Rs 20 per km. The cost is y = 20x + 100. The slope, 20, represents:",["the fixed charge","the cost per kilometre","the total distance","the waiting charge"],"B",3,1,"ba4edb3757f2"],["A ramp rises 3 m over a horizontal distance of 12 m. Its slope is:",["4","0.25","9","36"],"B",3,1,"4c4099ca4bc3"],["The points (1, 2), (2, 4) and (3, 6) are collinear because:",["the slope between each pair is 2","they are all in the first quadrant","their x-coordinates are consecutive","they form a right angle"],"A",5,0,"8dc11041a5b0"],["A line through (2, 1) and (k, 3) has slope 2. The value of k is:",["1","2","3","4"],"C",5,0,"4ac0f03ced3e"],["The point-slope form of a line through (x₁, y₁) with slope m is:",["y − y₁ = m(x − x₁)","y = mx","x − x₁ = m(y − y₁)","y + y₁ = m(x + x₁)"],"A",1,0,"c5727734861c"],["The slope of the line 4x − 2y + 7 = 0 is:",["2","−2","4","7/2"],"A",5,0,"69c3c373a87b"],["The slope of a line perpendicular to y = −3x + 1 is:",["3","−3","1/3","−1/3"],"C",3,0,"a0c38e86e5cf"],["The vertical line through (5, 2) has the equation:",["y = 2","x = 5","y = 5x + 2","x + y = 7"],"B",3,0,"7666e431bd67"],["A car's distance–time graph is a straight line through the origin. The slope of this line gives the car's:",["speed","acceleration","total distance","starting time"],"A",3,1,"398d1eaef2a0"],["The slope of the line through (2, 4) and (−4, −1) is:",["−5/6","6/5","−6/5","5/6"],"D",3,0,"gen-maths-m8-slope"],["The slope of the line through (−2, 2) and (0, −5) is:",["−7/2","−2/7","2/7","7/2"