select public.prepify_load_bank('Maths', 9, $j$[["The sum of the interior angles of a triangle is:",["90°","180°","270°","360°"],"B",1,0,"4988ce2f1fa1"],["The sum of the interior angles of a hexagon is:",["540°","720°","900°","1080°"],"B",3,0,"2cb5a6de7a54"],["Each interior angle of a regular pentagon is:",["72°","100°","108°","120°"],"C",3,0,"799c1be08dec"],["Each exterior angle of a regular octagon is:",["30°","40°","45°","60°"],"C",3,0,"8d29217e69f0"],["Each exterior angle of a regular polygon is 30°. The number of sides is:",["6","10","12","15"],"C",5,0,"9e7c44dbe704"],["The number of diagonals of a hexagon is:",["6","9","12","15"],"B",5,0,"88178efd128c"],["Two angles of a triangle are 50° and 60°. The third angle is:",["60°","70°","80°","90°"],"B",1,0,"5c4a00426a75"],["In a triangle, the two interior opposite angles are 40° and 65°. The exterior angle formed at the third vertex is:",["75°","105°","115°","140°"],"B",3,0,"a6a6d9437c8e"],["The legs of a right-angled triangle are 6 cm and 8 cm. The hypotenuse is:",["10 cm","12 cm","14 cm","48 cm"],"A",1,0,"11668a56342e"],["The hypotenuse of a right-angled triangle is 13 cm and one leg is 5 cm. The other leg is:",["8 cm","10 cm","12 cm","18 cm"],"C",3,0,"ef9db70faf2c"],["In a parallelogram, opposite angles are:",["equal","supplementary","complementary","always right angles"],"A",3,0,"e0e9226ec7de"],["The diagonals of a rhombus:",["bisect each other at right angles","are always equal","never meet","are parallel"],"A",3,0,"1550ac88fb56"],["The diagonals of a rectangle are:",["equal in length","perpendicular to each other","parallel","unequal"],"A",3,0,"4a9a93e0ca5a"],["Two triangles are congruent when two sides and the included angle of one equal those of the other. This is the:",["SSS rule","SAS rule","ASA rule","RHS rule"],"B",3,0,"2ceae9d4c6fb"],["Two right-angled triangles with equal hypotenuses and one pair of equal legs are congruent by the:",["SAS rule","ASA rule","RHS rule","AAA rule"],"C",3,0,"fd6c4333cc08"],["One of two angles on a straight line is 115°. The other is:",["55°","65°","75°","245°"],"B",1,0,"c1968b4e18e2"],["When two straight lines intersect, the vertically opposite angles are:",["equal","supplementary","complementary","always 90°"],"A",1,0,"d8d2db3cc9f7"],["When a transversal cuts two parallel lines, the alternate angles are:",["equal","supplementary","complementary","unequal"],"A",3,0,"9b2fd079b1f1"],["A transversal cuts two parallel lines. One of the co-interior angles is 110°. The other is:",["70°","80°","110°","250°"],"A",3,0,"07bb321d0481"],["Three angles of a quadrilateral are 80°, 95° and 105°. The fourth angle is:",["70°","80°","90°","100°"],"B",3,0,"64075ec49ab6"],["A tiler wants to cover a floor with identical regular hexagonal tiles leaving no gaps. This works because at each corner three angles of 120° make:",["180°","270°","360°","540°"],"C",3,1,"96c5b05db0be"],["The vertex angle of an isosceles triangle is 40°. Each base angle is:",["40°","60°","70°","140°"],"C",3,0,"2531a2683158"],["Each angle of an equilateral triangle is:",["45°","60°","90°","120°"],"B",1,0,"7c9770dae432"],["A 10 m ladder leans against a wall with its foot 6 m from the wall. How high up the wall does it reach?",["4 m","8 m","12 m","16 m"],"B",3,1,"492f51c3e6db"],["The sum of the exterior angles of any convex polygon is:",["180°","360°","540°","depends on the number of sides"],"B",3,0,"bd506a019bd3"],["Each interior angle of a regular polygon is 150°. The number of sides is:",["10","12","15","18"],"B",5,0,"28f270f982e3"],["A triangle with sides 3 cm, 4 cm and 5 cm is:",["acute-angled","right-angled","obtuse-angled","equilateral"],"B",3,0,"15bb2e2f9afe"],["Two similar triangles have corresponding sides 5 cm and 10 cm. The scale factor from the smaller to the larger is:",["1/2","2","5","10"],"B",3,0,"75065652f262"],["A polygon with all sides equal and all angles equal is called a:",["regular polygon","irregular polygon","trapezium","concave polygon"],"A",1,0,"3d299b93591d"],